require_once __DIR__.'/inc/ai/Bootstrap.php';header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');
try{if(!isUser())throw new RuntimeException('ابتدا وارد حساب پنل شوید و اتصال گوگل را دوباره آغاز کنید.');$state=$_GET['state']??'';if(!is_string($state))throw new RuntimeException('state معتبر نیست.');$key=hash('sha256',$state);$pending=$_SESSION['google_consent'][$key]??null;unset($_SESSION['google_consent'][$key]);if(!$pending||$pending['expires']<time())throw new RuntimeException('درخواست اتصال منقضی شده است.');$project=ModuleProjectAccess::select($pending['project']);$principal=AiAccess::principal($project);if($principal['owner']!==$pending['owner'])throw new RuntimeException('حساب اتصال تغییر کرده است.');(new AiGoogle(new AiStore()))->callbackToken($project,$principal,$pending['source'],$_GET['code']??'',$pending['revision']??null);header('Location: /panel/data-hub.php?project='.rawurlencode($project['id']).'&connected=1');exit;}catch(Throwable $e){http_response_code(400);echo htmlspecialchars($e instanceof RuntimeException?$e->getMessage():'اتصال گوگل انجام نشد.',ENT_QUOTES,'UTF-8');}
